<source id="1" url="https://chat.codercops.com/examples/vercel-full/" title="Vercel Edge Full Example" section="API Route (`api/chat.ts`)">
Vercel Edge Full Example > API Route (`api/chat.ts`)

```typescript
import { chatcopsVercelHandler } from '@chatcops/server';
import { LeadCaptureTool, FAQKnowledgeSource } from '@chatcops/core';

export const config = { runtime: 'edge' };

export default chatcopsVercelHandler({
  provider: {
    type: 'claude',
    apiKey: process.env.ANTHROPIC_API_KEY!,
    model: 'claude-haiku-5-5',
  },

  systemPrompt: `You are a helpful AI assistant for our SaaS product.
    Answer questions about features, pricing, and getting started.
    If a user shares contact info, capture it with the lead tool.`,

  tools: [
    new LeadCaptureTool(async (lead) => {
      // Send to webhook (e.g., Zapier, Make, n8n)
      await fetch(process.env.WEBHOOK_URL!, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'lead_captured',
          lead,
          timestamp: new Date().toISOString(),
        }),
      });
    }),
  ],

  knowledge: [
    new FAQKnowledgeSource([
      { question: 'What is your pricing?', answer: 'Starter: Free, Pro: $29/mo, Enterprise: Custom.' },
      { question: 'Is there a free trial?', answer: 'Yes, 14-day free trial on all paid plans.' },
      { question: 'What integrations do you support?', answer: 'Slack, Discord, Zapier, webhooks, and REST API.' },
    ]),
  ],

  allowedOrigins: ['*'],
  analytics: true,
});
```
</source>
<source id="2" url="https://chat.codercops.com/examples/express-full/" title="Express Full Example" section="Complete Server">
Express Full Example > Complete Server

```typescript
import express from 'express';
import { chatcopsMiddleware } from '@chatcops/server';
import { LeadCaptureTool, FAQKnowledgeSource, TextKnowledgeSource } from '@chatcops/core';

const app = express();
app.use(express.json());

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// ChatCops endpoint
app.all('/chat', chatcopsMiddleware({
  provider: {
    type: 'claude',
    apiKey: process.env.ANTHROPIC_API_KEY!,
    model: 'claude-haiku-5-5',
  },

  systemPrompt: `You are a helpful customer support assistant for Acme Corp.
    Be friendly, concise, and professional.
    If someone asks about pricing, refer to our plans: Starter ($0), Pro ($29/mo), Enterprise (custom).
    If someone shares their contact information or wants to be contacted,
    use the capture_lead tool to save their details.
    Always be transparent about being an AI assistant.`,

  tools: [
    new LeadCaptureTool(async (lead) => {
      console.log('New lead captured:', lead.email);
      // Save to database
      // await db.leads.create(lead);

      // Send to webhook/CRM
      // await fetch('https://hooks.zapier.com/...', {
      //   method: 'POST',
      //   body: JSON.stringify(lead),
      // });
    }),
  ],

  knowledge: [
    new FAQKnowledgeSource([
      { question: 'What are your business hours?', answer: '9am-5pm EST, Monday to Friday.' },
      { question: 'Do you offer refunds?', answer: 'Full refunds within 30 days of purchase.' },
      { question: 'How do I contact support?', answer: 'Email support@acme.com or use this chat.' },
      { question: 'What payment methods do you accept?', answer: 'Visa, Mastercard, PayPal, wire transfer.' },
      { question: 'Do you have an API?', answer: 'Yes! Check docs.acme.com for our REST API.' },
    ]),
    new TextKnowledgeSource([
      `Acme Corp was founded in 2020. We build AI-powered customer support tools.
      Our flagship product helps businesses add intelligent chat to their websites.
      We serve over 500 businesses across 30 countries.
      Our team is based in San Francisco, CA with remote employees worldwide.`,
    ]),
  ],

  webhooks: [
    {
      url: process.env.WEBHOOK_URL || 'https://hooks.example.com/chatcops',
      events: ['lead:captured'],
      secret: process.env.WEBHOOK_SECRET,
    },
  ],

  rateLimit: { maxRequests: 30, windowMs: 60_000 },
  analytics: true,
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') ?? ['*'],
}));

const PORT = process.env.PORT ?? 3001;
app.listen(PORT, () => {
  console.log(`ChatCops server running on http://localhost:${PORT}`);
});
```
</source>
<source id="3" url="https://chat.codercops.com/server/setup/" title="Server Setup" section="ChatCopsServerConfig">
Server Setup > ChatCopsServerConfig

```typescript
import type { AIProvider, Budgets, ChatCopsStorage, ChatTool, ConversationStore, KnowledgeSource, LocaleStrings, Logger, WebhookConfig } from '@chatcops/core';

interface ChatCopsServerConfig {
  // A config (see Providers for every option), or a provider object.
  provider:
    | { type: 'claude' | 'openai' | 'gemini'; apiKey: string; model?: string }
    | AIProvider;
  systemPrompt: string;
  tools?: ChatTool[];
  toolTimeoutMs?: number;
  maxTokens?: number;
  temperature?: number;
  knowledge?: KnowledgeSource[];
  budgets?: Budgets | false;   // on by default, see Budgets below
  preChatFields?: string[];   // pre-chat form fields to keep; kept from the first message on
  rateLimit?: {
    maxRequests: number;
    windowMs: number;
  };
  webhooks?: WebhookConfig[];
  analytics?: boolean;
  storage?: ChatCopsStorage;            // where conversations, counters and locks live
  retention?: { conversationsDays?: number };   // for purge(); default 30
  /** @deprecated Use `storage`. */
  conversationStore?: ConversationStore;
  allowedOrigins?: string[];   // default ['*']
  /** @deprecated Use `allowedOrigins`. */
  cors?: string;
  clientIp?: (request: Request) => string | null | undefined;   // fetch handlers, see the fetch runtimes page
  sessionSecrets?: string[];   // turns on session tokens, see Session tokens below
  sessionTtlSec?: number;      // default 900
  requireSession?: boolean;    // default true when sessionSecrets is set
  turnstile?: { secretKey: string; action?: string; expectedHostnames?: string[]; timeoutMs?: number };
  identity?: { secret: string; tiers?: Record<string, Budgets> };   // signed-in visitors, see below
  exposeUsage?: boolean;   // token usage in protocol v1 finish parts; default false
  logger?: Logger;         // where notes and errors go, see Logging below; default consoleLogger()
  /** @deprecated Ignored by the server. Use the widget's `strings` option. */
  i18n?: {
    defaultLocale: string;
    locales: Record<string, LocaleStrings>;
  };
}
```
</source>
<source id="4" url="https://chat.codercops.com/" title="ChatCops Documentation" section="Architecture">
ChatCops Documentation > Architecture

```
┌──────────────────┐         ┌──────────────────┐
│   Your Website   │  SSE    │   Your Server    │
│                  │ ──────► │                  │
│  <script> tag    │ ◄────── │  @chatcops/server│
│  @chatcops/widget│ stream  │  ├─ Provider     │
│  Shadow DOM      │         │  ├─ Knowledge    │
│  Chat Panel      │         │  ├─ Tools        │
└──────────────────┘         │  └─ Analytics    │
                             └──────────────────┘
```
</source>
<source id="5" url="https://chat.codercops.com/widget/api/" title="API Reference" section="Auto-Initialization &gt; Inline">
API Reference > Auto-Initialization > Inline

```html
<div id="my-chat" style="width: 400px; height: 500px;"></div>
<script
  src="https://cdn.jsdelivr.net/npm/@chatcops/widget/dist/chatcops.min.js"
  data-api-url="https://your-api.com/chat"
  data-mode="inline"
  data-container="#my-chat"
></script>
```

The script tag approach is equivalent to calling `ChatCops.init()` with the corresponding config. You can still use the programmatic API after auto-init (e.g., `ChatCops.open()`).
</source>
</sources>

